import {payloadOf,markSynced,mergeSessions} from './sync-model.mjs';
let client;
export async function getClient(){if(!client){const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.57.4');client=createClient('https://qbhoglehjamqvbyzkdiy.supabase.co','sb_publishable_EXh8CH7WVgrkEZ6OlvbBSQ_weLK-ZDL');}return client;}
export async function login(email,password,create=false){const c=await getClient();const r=create?await c.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin+'/'}}):await c.auth.signInWithPassword({email,password});if(r.error)throw r.error;return r.data.session;}
export async function cloudUser(){const c=await getClient();const {data,error}=await c.auth.getUser();if(error){if(/session.*missing|not authenticated/i.test(error.message))throw new Error('Entre na sua conta Borali antes de sincronizar.');throw error;}if(!data.user)throw new Error('Conta não autorizada para este Borali.');return data.user;}
export async function syncState(localSessions,localProfile){const c=await getClient();await cloudUser();let remote=[];for(let from=0;;from+=500){const {data,error}=await c.from('borali_sessions').select('id,payload,revision').order('id').range(from,from+499);if(error)throw error;remote.push(...data);if(data.length<500)break;}
const merged=mergeSessions(localSessions,remote);if(merged.conflicts.length)throw new Error('Edição diferente em outro aparelho. Seu histórico local foi preservado. Exporte um backup antes de resolver o conflito.');
let result=[];for(const item of merged.sessions){const doc=payloadOf(item);if(doc.status!=='finished'||JSON.stringify(doc)===item._cloud?.base){result.push(item);continue;}const {data,error}=await c.rpc('borali_save_session',{doc,expected_revision:item._cloud?.revision??0});if(error)throw new Error('Não foi possível salvar a caminhada na nuvem. '+(error.code==='40001'||error.code==='23505'?'Há conflito entre aparelhos.':'Tente novamente.'));result.push(markSynced(data.payload,data.revision));}
const {data:pr,error:pe}=await c.from('borali_profiles').select('payload,revision').maybeSingle();if(pe)throw pe;let profile=localProfile,doc=payloadOf(profile),json=JSON.stringify(doc);if(pr){if(json===JSON.stringify(pr.payload))profile=markSynced(pr.payload,pr.revision);else if(pr.revision!==profile._cloud?.revision){if(!Object.keys(doc).length||json===profile._cloud?.base)profile=markSynced(pr.payload,pr.revision);else throw new Error('Perfil alterado em outro aparelho. Perfil local preservado.');}}
if(JSON.stringify(payloadOf(profile))!==profile._cloud?.base){const {data,error}=await c.rpc('borali_save_profile',{doc:payloadOf(profile),expected_revision:profile._cloud?.revision??0});if(error)throw new Error('Perfil não sincronizado. Confira a conexão e tente novamente.');profile=markSynced(data.payload,data.revision);}
return {sessions:result,profile};}
